mapper.select:
select `applicant_id` as `userId`,`applicant_name` as `userName`,
SUM(IF(`work_type`='WORK',work_duration,0)) as 'workDuration',
SUM(IF(`work_type`='REST',work_duration,0)) as 'restDuration',
SUM(IF(`work_type`='FESTIVAL',work_duration,0)) as 'festivalDuration'
from `work_overtime_situation`
where `compensate` = 'FEE' and `tenant` = #{param.tenant} and `deleted` = 0

    and `applicant_dept_id` = #{param.deptId}


    and `attendance_group_id` = #{param.groupId}


    and `start_time` >= #{param.startTime}


    and `start_time` < #{param.endTime}


    and `applicant_name` like CONCAT('%',#{param.userName},'%')

GROUP BY `applicant_id`

select SUM(`work_duration`)
from `work_overtime_situation`
where `tenant` = #{param.tenant} and `deleted` = 0

    and `applicant_dept_id` = #{param.deptId}


    and `attendance_group_id` = #{param.groupId}


    and `start_time` >= #{param.startTime}


    and `start_time` < #{param.endTime}

select os.`applicant_id` as `userId`,
SUM(IF(os.`work_type` = 'WORK',os.`work_duration`,0)) AS 'overtimeWorkDuration',
SUM(IF(os.`work_type` = 'REST',os.`work_duration`,0)) AS 'overtimeRestDuration',
SUM(IF(os.`work_type` = 'FESTIVAL',os.`work_duration`,0)) AS 'overtimeFestDuration'
from `work_overtime_situation` os
where os.`deleted` = 0

    and os.`applicant_id` = #{param.userId}


    and os.`applicant_id` in

        #{id}



    and os.`start_time` >= #{param.period.begin}


    and os.`start_time` < #{param.period.end}

group by os.`applicant_id`

select os.`applicant_id` as `staff_Id`,
SUM(IF(os.`work_type` = 'WORK',os.`work_duration`,0)) AS 'overtime_Work_Duration',
SUM(IF(os.`work_type` = 'REST',os.`work_duration`,0)) AS 'overtime_Rest_Duration',
SUM(IF(os.`work_type` = 'FESTIVAL',os.`work_duration`,0)) AS 'overtime_Fest_Duration'
from `work_overtime_situation` os
where os.`deleted` = 0

    and os.`applicant_id` = #{param.userId}


    and os.`applicant_id` in

        #{id}



    and os.`start_time` >= #{param.period.begin}


    and os.`start_time` < #{param.period.end}

group by os.`applicant_id`
